    <div class="row">
      <button class="btn-ghost" onclick="closeModal()">Cancelar</button>
      <button class="btn-primary" onclick="saveKey()">Guardar</button>
    </div>
  </div>
</div>

<script>
  const MODELS = {
    A: "gemini-2.5-flash",
    B: "gemini-2.5-pro"
  };
  const history = { A: [], B: [] };
  let apiKey = localStorage.getItem("gemini_key") || "";

  const $ = (id) => document.getElementById(id);
  const statusDot = $("statusDot");
  const overlay = $("overlay");

  function updateStatus(){
    if(apiKey){
      statusDot.classList.add("ok");
      statusDot.title = "Conectado";
    } else {
      statusDot.classList.remove("ok");
      statusDot.title = "Sin API Key";
    }
  }

  function openModal(){ overlay.classList.add("show"); $("apiKey").value = apiKey; $("apiKey").focus(); }
  function closeModal(){ overlay.classList.remove("show"); }
  function saveKey(){
    apiKey = $("apiKey").value.trim();
    localStorage.setItem("gemini_key", apiKey);
    updateStatus();
    closeModal();
  }
  $("btnKey").onclick = openModal;

  // Sync = envía el mismo mensaje a ambos procesos
  $("btnSync").onclick = async () => {
    const a = $("inputA").value.trim();
    const b = $("inputB").value.trim();
    const text = a || b;
    if(!text) return;
    $("inputA").value = ""; $("inputB").value = "";
    await Promise.all([sendInternal("A", text), sendInternal("B", text)]);
  };

  // Auto-grow textareas
  ["inputA","inputB"].forEach(id=>{
    const ta = $(id);
    ta.addEventListener("input", () => {
      ta.style.height = "auto";
      ta.style.height = Math.min(ta.scrollHeight, 120) + "px";
    });
  });

  function send(which, ev){
    ev && ev.preventDefault();
    const input = $("input" + which);
    const text = input.value.trim();
    if(!text) return false;
    input.value = "";
    input.style.height = "auto";
    sendInternal(which, text);
    return false;
  }

  function addMessage(which, role, content, opts={}){
    const chat = $("chat" + which);
    // Remove welcome
    const welcome = chat.querySelector(".welcome");
    if(welcome) welcome.remove();

    const el = document.createElement("div");
    el.className = "msg " + (opts.class || role);
    el.textContent = content;
    chat.appendChild(el);
    chat.scrollTop = chat.scrollHeight;
    return el;
  }

  function clearChat(which){
    history[which] = [];
    const chat = $("chat" + which);
    chat.innerHTML = '<div class="welcome"><b>Historial limpiado</b></div>';
  }

  function copyLast(which){
    const msgs = history[which].filter(m => m.role === "model");
    if(!msgs.length) return;
    const last = msgs[msgs.length - 1];
    const text = (last.parts && last.parts[0] && last.parts[0].text) || "";
    navigator.clipboard.writeText(text);
  }

  async function sendInternal(which, text){
    if(!apiKey){ openModal(); return; }

    addMessage(which, "user", text);
    history[which].push({ role: "user", parts: [{ text }] });

    const thinkingEl = addMessage(which, "bot", "…", { class: "bot typing" });
    $("send" + which).disabled = true;

    const url = `https://generativelanguage.googleapis.com/v1beta/models/${MODELS[which]}:streamGenerateContent?alt=sse&key=${encodeURIComponent(apiKey)}`;

    try {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ contents: history[which] })
      });

      if(!res.ok){
        const errTxt = await res.text();
        throw new Error("HTTP " + res.status + " — " + errTxt.slice(0, 200));
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let fullText = "";
      thinkingEl.textContent = "";
      thinkingEl.classList.remove("typing");

      while(true){
        const { done, value } = await reader.read();
        if(done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop();
        for(const line of lines){
          if(!line.startsWith("data: ")) continue;
          const data = line.slice(6).trim();
          if(!data || data === "[DONE]") continue;
          try {
            const json = JSON.parse(data);
            const parts = json.candidates?.[0]?.content?.parts || [];
            for(const p of parts){
              if(p.text){
                fullText += p.text;
                thinkingEl.textContent = fullText;
                const chat = $("chat" + which);
                chat.scrollTop = chat.scrollHeight;
              }
            }
          } catch(e){ /* ignore */ }
        }
      }

      if(fullText){
        history[which].push({ role: "model", parts: [{ text: fullText }] });
        const meta = document.createElement("span");
        meta.className = "meta";
        meta.textContent = MODELS[which] + " · " + new Date().toLocaleTimeString();
        thinkingEl.appendChild(meta);
      } else {
        thinkingEl.classList.add("err");
        thinkingEl.textContent = "Sin respuesta del modelo.";
      }

    } catch(err){
      thinkingEl.classList.remove("typing");
      thinkingEl.classList.add("err");
      thinkingEl.textContent = "⚠ " + err.message;
    } finally {
      $("send" + which).disabled = false;
    }
  }

  updateStatus();
  if(!apiKey) setTimeout(openModal, 300);
</script>

</body>
</html>
